import json,csv,re,hashlib,statistics as st,math,random
T=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
S=list(csv.DictReader(open('data/scores.csv')))
print(len(T),len(S), hashlib.sha256(open('data/scores.csv','rb').read()).hexdigest())
td={t['rating_id']:t for t in T}
mm=[]
for r in S:
    t=td[r['rating_id']]
    m=re.findall(r'FINAL SCORE:\s*(\d+)',t['judge_output'])
    if len(m)!=1 or int(m[-1])!=int(r['score']) or t['displayed_label']!=r['displayed_label'] or t['response_id']!=r['response_id'] or str(t['session'])!=r['session']:
        mm.append((r['rating_id'],r['response_id'],r['displayed_label'],r['session'],r['score'],m,t['judge_output']))
for x in mm: print(x)
print(len(mm))
print(set(t['judge_model'] for t in T))
for t in T:
    if not t['judge_output'].startswith('Displayed author: '+t['displayed_label']): print('label mismatch',t)
def eff(src):
    d={}
    for rid,lab,sc in src: d.setdefault(rid,{})[lab]=sc
    diffs=[v['atlas-7']-v['nova-3'] for v in d.values()]
    return diffs
dS=eff([(r['response_id'],r['displayed_label'],int(r['score'])) for r in S])
dT=eff([(t['response_id'],t['displayed_label'],int(re.findall(r'FINAL SCORE:\s*(\d+)',t['judge_output'])[-1])) for t in T])
for name,d in [('sheet',dS),('transcript',dT)]:
    n=len(d);m=st.mean(d);sd=st.stdev(d);se=sd/math.sqrt(n)
    # sign-flip permutation
    random.seed(0);obs=abs(sum(d));cnt=0;N=100000
    for _ in range(N):
        if abs(sum(x*random.choice((1,-1)) for x in d))>=obs-1e-9: cnt+=1
    print(name,n,round(m,3),round(sd,3),round(se,3),(round(m-2.045*se,2),round(m+2.045*se,2)),sum(x>0 for x in d),sum(x<0 for x in d),sum(x==0 for x in d),cnt/N)
